"use client"

/** Independent implementation of a common dashboard pattern. */

import * as React from "react"
import { ArrowDownRight, ArrowUpRight } from "lucide-react"

import { cn } from "@/lib/utils"
import { formatDashboardValue, type DashboardFormat } from "@/lib/dashboard-format"

export type StatDelta = {
  value: number
  format?: DashboardFormat
  /** Visual arrow. Inferred from the sign when omitted. */
  direction?: "up" | "down"
  /** Which direction counts as an improvement. */
  good?: "up" | "down"
  label?: string
}

export type StatStripItem = {
  id: string
  label: string
  value: number | string
  format?: DashboardFormat
  currency?: string
  delta?: StatDelta
  caption?: string
  /** Inverted tile. Used with variant="tiles". */
  featured?: boolean
}

export type StatStripClassNames = {
  root?: string
  item?: string
  label?: string
  value?: string
  delta?: string
  caption?: string
}

export type StatStripProps = {
  items: readonly StatStripItem[]
  variant?: "inline" | "panel" | "tiles"
  locale?: string
  className?: string
  classNames?: StatStripClassNames
}

function deltaDirection(delta: StatDelta): "up" | "down" {
  if (delta.direction) return delta.direction
  return delta.value < 0 ? "down" : "up"
}

function deltaIsGood(delta: StatDelta): boolean {
  const direction = deltaDirection(delta)
  return direction === (delta.good ?? "up")
}

function deltaText(delta: StatDelta, locale: string): string {
  if (delta.label) return delta.label
  return formatDashboardValue(delta.value, delta.format ?? "number", locale)
}

export function statAccessibleName(item: StatStripItem, locale: string): string {
  const value = formatDashboardValue(item.value, item.format ?? "text", locale, item.currency)
  if (!item.delta) return [item.label, value, item.caption].filter(Boolean).join(", ")
  const direction = deltaDirection(item.delta)
  const quality = deltaIsGood(item.delta) ? "better" : "worse"
  return [item.label, value, direction, deltaText(item.delta, locale), item.caption, quality].filter(Boolean).join(", ")
}

export function StatStrip({ items, variant = "inline", locale = "en-US", className, classNames }: StatStripProps) {
  return (
    <div
      data-slot="stat-strip"
      data-variant={variant}
      className={cn(
        "@container min-w-0",
        variant === "panel"
          ? "grid grid-cols-1 overflow-hidden rounded-xl bg-card text-card-foreground @min-[16rem]:grid-cols-2 @min-[36rem]:grid-cols-4"
          : variant === "tiles"
            ? "grid grid-cols-2 gap-2 @min-[36rem]:grid-cols-4"
            : "flex min-w-0 flex-wrap gap-x-6 gap-y-3",
        className,
        classNames?.root,
      )}
    >
      {items.map((item, index) => {
        const value = formatDashboardValue(item.value, item.format ?? "text", locale, item.currency)
        const direction = item.delta ? deltaDirection(item.delta) : null
        const good = item.delta ? deltaIsGood(item.delta) : false
        const Icon = direction === "down" ? ArrowDownRight : ArrowUpRight
        return (
          <div
            key={item.id}
            data-slot="stat-strip-item"
            className={cn(
              "min-w-0",
              variant === "inline" && "min-w-36 shrink-0",
              variant === "panel" && "border-border px-4 py-3 @min-[16rem]:border-s @min-[16rem]:[&:nth-child(2n+1)]:border-s-0 @min-[36rem]:[&:nth-child(2n+1)]:border-s @min-[36rem]:first:border-s-0",
              variant === "panel" && index > 0 && "border-t @min-[16rem]:border-t-0",
              variant === "tiles" && "rounded-xl bg-muted px-3 py-3",
              variant === "tiles" && item.featured && "bg-foreground text-background",
              classNames?.item,
            )}
          >
            <p className={cn("text-xs", item.featured && variant === "tiles" ? "text-background/70" : "text-muted-foreground", classNames?.label)}>{item.label}</p>
            <p className={cn("mt-1 flex flex-wrap items-center gap-2 text-3xl font-normal tabular-nums tracking-tight", classNames?.value)}>
              <span className="break-words">{value}</span>
              {item.delta && direction ? (
                <span
                  className={cn(
                    "inline-flex items-center gap-0.5 text-sm tabular-nums",
                    good ? "text-foreground" : "text-destructive",
                    classNames?.delta,
                  )}
                >
                  <span className={cn("grid size-5 place-items-center rounded-full", good ? "bg-chart-2/20" : "bg-destructive/10")} aria-hidden>
                    <Icon className="size-3.5" />
                  </span>
                  {deltaText(item.delta, locale)}
                </span>
              ) : null}
            </p>
            {item.caption ? <p className={cn("mt-1 text-xs text-muted-foreground", classNames?.caption)}>{item.caption}</p> : null}
            <span className="sr-only">{statAccessibleName(item, locale)}</span>
          </div>
        )
      })}
    </div>
  )
}

/** Number, date, and greeting helpers for dashboard pieces. No theme tokens. */

export type DashboardFormat = "number" | "currency" | "percent" | "compact" | "text" | "points"

export function formatDashboardValue(
  value: number | string,
  format: DashboardFormat = "text",
  locale = "en-US",
  currency = "USD",
): string {
  if (typeof value !== "number" || !Number.isFinite(value) || format === "text") return String(value)
  if (format === "currency") {
    return new Intl.NumberFormat(locale, {
      style: "currency",
      currency,
      notation: Math.abs(value) >= 10000 ? "compact" : "standard",
      maximumFractionDigits: Math.abs(value) >= 10000 ? 1 : 0,
    }).format(value)
  }
  if (format === "percent") {
    return new Intl.NumberFormat(locale, {
      style: "percent",
      maximumFractionDigits: 1,
    }).format(value)
  }
  if (format === "compact") {
    return new Intl.NumberFormat(locale, { notation: "compact", maximumFractionDigits: 1 }).format(value)
  }
  if (format === "points") {
    const formatted = new Intl.NumberFormat(locale, {
      signDisplay: "exceptZero",
      maximumFractionDigits: 1,
    }).format(value)
    return `${formatted} pts`
  }
  return new Intl.NumberFormat(locale, { maximumFractionDigits: 1 }).format(value)
}

export function formatDashboardDate(
  value: string | number | Date,
  locale = "en-US",
  options: Intl.DateTimeFormatOptions = { month: "short", day: "numeric" },
): string {
  const date = value instanceof Date ? value : new Date(value)
  if (Number.isNaN(date.getTime())) return String(value)
  return new Intl.DateTimeFormat(locale, options).format(date)
}

export function joinMeta(parts: Array<string | number | null | undefined | false>): string {
  return parts.filter((part) => part != null && part !== false && part !== "").map(String).join(" · ")
}

const DAY_PART = {
  en: { morning: "Good morning", afternoon: "Good afternoon", evening: "Good evening" },
  es: { morning: "Buenos días", afternoon: "Buenas tardes", evening: "Buenas noches" },
} as const

/** Time-of-day greeting. Spanish locales use es; everything else uses en. */
export function greeting(date: Date, locale: string, name: string): string {
  const hour = date.getHours()
  const part = hour < 12 ? "morning" : hour < 18 ? "afternoon" : "evening"
  const table = locale.toLowerCase().startsWith("es") ? DAY_PART.es : DAY_PART.en
  return `${table[part]}, ${name}`
}

export function shareOf(value: number, total: number): number {
  if (!Number.isFinite(value) || !Number.isFinite(total) || total <= 0) return 0
  return value / total
}

export function clampRatio(value: number, min: number, max: number): number {
  const span = max - min
  if (!Number.isFinite(span) || span <= 0) return 0
  return Math.min(1, Math.max(0, (value - min) / span))
}

export type RankedInput = { id: string; value: number; share?: number }

export function orderRanked<T extends RankedInput>(items: readonly T[], sort: "asc" | "desc" | "none" = "desc"): T[] {
  const copy = items.map((item) => ({ ...item }))
  if (sort === "asc") copy.sort((a, b) => a.value - b.value || a.id.localeCompare(b.id))
  if (sort === "desc") copy.sort((a, b) => b.value - a.value || a.id.localeCompare(b.id))
  const total = copy.reduce((sum, item) => sum + (Number.isFinite(item.value) ? item.value : 0), 0)
  return copy.map((item) => ({ ...item, share: item.share ?? shareOf(item.value, total) }))
}

/** Delay in seconds for a short opacity stagger. Zero when motion is reduced. */
export function staggerDelay(index: number, reduced: boolean, step = 0.04): number {
  if (reduced || index <= 0) return 0
  return index * step
}
